    spLadderDesc: 'Na-abawanye kwa izuụka iri na abụọ, na oge ole nke ọ bụla na-agba ọsọ. O nweghị kọlụm ọ bụla na-agbadata ka ị na-arịgo, ma ngụkọta ya na-abawanye mgbe niile.',
