    spNoAllowance: 'Enweghị ego',
    spPowersLead: 'Onye ọ bụla rung nke baajị ladder unlocks kpọmkwem otu ike, na onye ọ bụla ike ị unlocked anọ unlocked. Ha niile na-adọta n \'otu ego a na-enye kwa izuụka abụọ, ya bụ nhọrọ bụ ihe a ga-eji ya emefu.',
    spRotationTitle: 'Otu esi ekekọrịta oghere ahụ',
    spSafetyDesc: 'Kwa ịbịaru na-re-enyocha megide post dị ka ọ na-eguzo n \'oge ahụ, otú a post na kemgbe e wepụrụ, egbochi ma ọ bụ akara tozuru okè mgbe esịmde a ọbịbịa nri. Okenye posts na-jụrụ na ntinye akwụkwọ oke, na a mbo mbuli dịghị mgbe e mesoro onye na-egbochi gị ma ọ bụ onye ị boosted.',
    spSafetyTitle: 'Ihe nkwalite enweghị ike ime',
