    spTierLobster: 'Ghost Lobster',
    spTierPiranha: 'Piranha',
    spUnlocksAt: 'Ị kpọghee ekwt na',
    stagesB2Desc: 'Na-ege ntị na-eziga ndụ emoji mmeghachi omume, na usu ụgbọala a DJ-ụdị soundboard na click-free cueing na olu mmetụta agwakọta kpọmkwem n \'ime ụlọ audio.',
    stagesB4: 'Ihe ndekọ:',
    stagesB6Desc: 'Ndụ captions maka onye ọ bụla na-ekwu okwu, sụgharịa n \'asụsụ onye ọ bụla na-ege ntị na-agụ. A na-edebe ihe odide ahụ na-adịgide adịgide iche iche mgbe ọnụ ụlọ ahụ gwụchara.',
    stagesDesc: 'Ogbo bụ ime ụlọ ọdịyo dị ndụ, nke e jiri ya tụnyere Twitter Spaces, nke e wuru kpọmkwem n \'ime DeHub. Onye ọbịa meghere ime ụlọ, wetara ndị ọkà okwu n\' ogbo, ma ọnụ ọgụgụ ọ bụla nke ndị na-ege ntị nwere ike ịdaba ozugbo site na peeji nke ogbo ma ọ bụ njikọ ịkpọ òkè. Ezubere usoro maka ezigbo mkparịta ụka n \'ọtụtụ: ndị ọbịa na-achịkwa ndị nwere ike ikwu okwu, ndị na-ege ntị na-ezipụ mmeghachi omume ndụ, ma enwere ike ịdekọ ọnụ ụlọ ahụ dum maka ịmegharị.',
    stagesTitle: 'Ogbo: Live Audio Ụlọ',
    storesB2: 'Ree maka Tokens:',
    storesB2Desc: 'Ngwaahịa na-ọnụ na biri na DeHub tokens site wuru na-na wallet, na-enweghị mpụga ndenye ọpụpụ.',
    storesDesc: 'Store ka creators na ulo oru na-emeghe a nwa afọ storefront n \'ime DeHub na-ere ozugbo ha na-ege ntị, biri na DeHub tokens. Ụlọ ahịa na-ebi na peeji nke ya, na-anọdụ n\' akụkụ ọdịnaya nke onye okike, ma na-atụgharị ndị na-eso ụzọ n \'ime ndị ahịa na-enweghị ibugharị ha na ndenye ọpụpụ. N\' ihi na ugwo-agba site na otu wuru na obere akpa dị ka ndị ọzọ nke ngwa, na-azụ ahịa nwere ike ịzụta na a di na nwunye nke taps na-ere ahịa na-enweta tokens ozugbo ha itule.',
    studioB1Desc: 'Images, video, music, voiceover na 3D ụdị, gafee ụdị ndị Studio na-ekpughe, ọnụ na kwuru site na ihe nkesa tupu a ọrụ na-agba ọsọ.',
    studioB2Desc: 'A multi-track usoro iheomume nchịkọta akụkọ na nchọgharị, na mbupụ. Ọ dịghị ihe a ga-etinye na ọ dịghị ihe a ga-ebugo na nke atọ.',
    studioB3Desc: 'Ndị na-enye onyinye na-aga n \'ihu n\' ahịrị a na-ekerịta mgbe ị na-agagharị, ma ọbá akwụkwọ ihe onwunwe n \'efu na-ekpuchi oghere ndị ahụ.',
    studioB4: 'Ebe E Si Nweta ma ọ bụ atụmatụ:',
    studioDesc: 'Onye Okike Studio bụ ebe a na-eme ọdịnaya karịa biputere. Ọ n \'ịwa oyiyi, video, music, olu na 3D ụdị si a ozugbo, na-eme a nsụgharị kwụ n\' ahịrị na-arụ ọrụ mgbe ị na-ebu na-eme nchọgharị na ngwa, na aka na-arụpụta a Canva-style nchịkọta akụkọ maka ndokwa, cropping na captioning. A free ngwaahịa akpan owo n \'ọbá akwụkwọ na-anọdụ n\' akụkụ ya, otú a post nwere ike wuru ọgwụgwụ na-akwụsị enweghị mpụga ngwá ọrụ ma ọ bụ a ndenye aha na otu.',
    studioDesc2: 'Ọzọ ya bụ a full video nchịkọta akụkọ na-agba na nchọgharị — a n \'ezie multi-track usoro iheomume na ọnwụ, n\' ígwé na mbupụ, ọ bụghị a ewepụtụ slider. Footage ị mere na Studio, media ị uploaded na ihe ọ bụla si akụ n \'ọbá akwụkwọ niile dobe jidesie otu usoro iheomume, na okokụre ịkpụ na-aga kpọmkwem n\' ime a post, a obere ma ọ bụ a ụlọ ahịa ndepụta.',
    superPowersDescV2: 'SuperPowers tụgharịa a staking baajị n \'ime iru ị nwere ike imefu. Kwa izu abụọ ọ bụla baajị gị na-abawanye, ma na-emefu otu na-etinye post n\' ime oghere dị n \'elu nri ụlọ. Team elu bụ na-emeghe ka onye ọ bụla na-agwakọta obere akpa ike nke ruo asatọ akaụntụ, na-enye onye ọ bụla so na baajị ha ngụkọta unlocks. The oghere rotates: mgbe ọtụtụ boosts na-agba ọsọ, na-ekiri na-emeso otu weighted site baajị tier, otú a elu tier na-egosi ọzọ mgbe na onye ọ bụla ka na-akawanye window ha e nyere.',
    superPowersMore2: 'Ike iri na abụọ niile dị ndụ ma depụta ya n \'ime ngwa ahụ. Comment Anchor na-ejide okwu gị n\' elu eriri onye ọzọ. Signal Flare na-eziga otu ọkwa na akaụntụ ọ bụla na-eso gị. Flak Jacket na-eme ka a post-ekwesịghị ime ka downvote ili mgbe ọ na-agba ọsọ. Team elu ka ọtụtụ dị ka asatọ akaụntụ ikpokọta ha obere akpa ike, otú ọ bụla so na-eyi baajị ha pooled itule unlocks. Front Row na-etinye Stage ị na-anabata na n \'elu nke ogbo okporo ígwè. Deep Current na-enye otu n \'ime nkwalite gị na post onye ọzọ.',
    superPowersMoreV2: 'Ike iri na abụọ niile dị ndụ ma depụta ya n \'ime ngwa ahụ. Comment Anchor na-ejide okwu gị n\' elu eriri onye ọzọ. Signal Flare na-eziga otu ọkwa na akaụntụ ọ bụla na-eso gị. Flak Jacket na-eme ka a post-ekwesịghị ime ka downvote ili mgbe ọ na-agba ọsọ. Team elu ka ọtụtụ dị ka asatọ akaụntụ ikpokọta ha obere akpa ike, otú ọ bụla so na-eyi baajị ha pooled itule unlocks. Front Row na-etinye Stage ị na-anabata na n \'elu nke ogbo okporo ígwè. Deep Current na-enye otu n \'ime nkwalite gị na post onye ọzọ.',
    themesDesc2: 'Abụọ n \'ime akpụkpọ ahụ na-ezo egwuregwu. Debe isiokwu ahụ na Agha na Claude nke Ọrụ nwere ike ịnweta site n\' ime ya; debe ya na Jungle na Jungle Trail bụ. Ha abụọ nọkwa na arcade, mana isiokwu bụ ebe ha nọ.',
