    trendJackerDesc2: 'Tinye otu n \'ime edemede gị n\' elu ndepụta na-ewu ewu. Ị kpọghee ekwt na Giant Tortoise. Biri ugbu a.',
    tvRadioB2Desc: 'A raara onwe ya nye music elu na taabụ maka tracks, music videos, pọdkastị na ndụ arụmọrụ, onye ọ bụla na ya onwe ya ọkpụkpọ.',
    tvRadioB3: 'Ngwaahịa:',
    tvRadioDesc: 'Beyond creator uploads, DeHub ụgbọ mmiri mgbe nile-na ntụrụndụ na-ebupụta otú e nwere ihe na-ekiri ma ọ bụ na-ege ntị oge ị na-emeghe ngwa. Ndị a dabere-azụ ahụmahụ na-agba ọsọ nọgidere na-eso gị gburugburu ngwaahịa site sere n \'elu egwuregwu, otú media mgbe akwụsị mgbe ị na-agagharị n\' ebe ndị ọzọ.',
    walletHubB1: 'Akpa ego:',
    walletHubB2: 'Ebe iwu:',
    walletHubB2Desc: 'A okike ego dashboard na ego chaatị karịrị oge, kwa-azụmahịa breakdowns na a cross-yinye nkwụnye ego drawer.',
    walletHubDesc: 'Akaụntụ DeHub ọ bụla na-abịa na obere akpa e wuru n \'ime ya, nke na-abụghị nke nchekwa. E nweghị ihe nchọgharị extensions iji wụnye na ọ dịghị mkpụrụ nkebi ahịrịokwu jikwaa: obere akpa na-kere na chebere gị oge mbụ ị banye na, na ọ ike ọ bụla uru nyefe na ngwa, si tipping na-akwụ kwa-view unlocks na ndenye aha, bounties na Onye Okike ịkpata. Izipu tokens ọzọ ọrụ bụ free, na abstraction ngwaọrụ pụtara ọtụtụ ọrụ mgbe aka a raw obere akpa adreesị ma ọ bụ onwe igodo.',
    walletHubDesc2: 'Maka ndị na-emepụta ihe na ndị na-eji ike eme ihe, obere akpa ahụ na-agbasawanye n \'elu ego zuru oke. The Command Centre visualises ego karịrị oge, emebi ọ bụla azụmahịa, na-ejikwa cross-yinye ego, mgbe raara onwe ya nye peeji nke ka ị ịzụta, osisi na àkwà mmiri DeHub tokens enweghị na-ahapụ DeHub.',
    walletHubLink: 'Hụ akwụkwọ Token maka akụnụba, staking na bridging na omimi.',
    workB1Desc: 'Onye ọ bụla nwere ike biputere a mmesapụ na a doro anya nkenke na a ụgwọ ọrụ na DeHub tokens ma ọ bụ USDC, ma ọ bụ a mpempe ọrụ na-anapụta ma ọ bụ ihe njikọ aka ọrụ dị ka nkekọrịta, clipping ma ọ bụ na-akwalite ọdịnaya.',
    workB2Desc: 'Chọgharịa na-emeghe bounties, nyo site Atiya ma ọ bụ ego, na-ekwu na ndị ị chọrọ, ma nyefee ọrụ gị na-anakọta ụgwọ ọrụ. Onye ọ bụla ọrụ nwere ike ịbụ a dinta, ọ dịghị ngwa ma ọ bụ nche ọnụ ụzọ ámá chọrọ.',
    workB3Desc: 'A na-ahazi onyinye n \'ime Social Media, Clipping na Contracts, ya mere ọrụ ntinye aka na ogologo ọrụ nke ọ bụla nwere ụzọ nke ha.',
    workB4: 'Escrow Nchedo:',
    workB5Desc: 'Creators post bounties na-eto eto ha obodo, na DeHub obodo posts bounties onwe-akwalite ma mụbaa na gburugburu ebe obibi, mbịne nkwalite n \'ime a ụgwọ ọrụ, trackable ọrụ.',
    workB6: 'Arụmụka:',
    workB6Desc: 'A raara onwe ya nye esemokwu eruba edozi esemokwu banyere nnyefe, otú escrowed ụgwọ ọrụ na-mgbe edozi ezi.',
    workDesc: 'Bounty Hunting bụ DeHub si wuru na-ọrụ na ụgwọ ọrụ usoro, ọ bụghị a-atọ ndị ọzọ freelance n \'ọma ahịa. Onye ọ bụla na gburugburu ebe obibi nwere ike biputere a mmesapụ, na onye ọ bụla nwere ike ịghọ a dinta na-azọrọ na ya, na ụgwọ ọrụ ẹkenịmde n\' enweghị ruo mgbe ọrụ na-anapụta. Ọ amama ọrụ na njikọ aka n \'ime a nwa afọ akụkụ nke n\' elu ikpo okwu: ndị mmadụ ikenye bounties, dinta okokụre ha na tokens na-edozi ha niile na-ebi n \'ime DeHub. A na-akwụ ụgwọ ego na DeHub tokens ma ọ bụ USDC.',
    workDesc2: 'N \'ihi na ọ bụ nwa afọ, Bounty Hunting okpukpu abụọ dị ka a ibu engine maka dum gburugburu ebe obibi. Creators iji ya ụgbọala njikọ aka na-ewu ha obodo site ikenye bounties maka mbak, mkpachị, mmeghachi omume ma ọ bụ ọdịnaya na-agbasa ọrụ ha. Projects na wider DeHub obodo iji ya onwe-akwalite na-eto eto na gburugburu ebe obibi, na-akwụghachi ụgwọ dinta maka ihe aga-eme na-eweta ọhụrụ ndị mmadụ na. Otu usoro ahụ nke na-edozi nkwekọrịta na-edozi ọrụ njikọ aka obodo.',
    workTitle: 'Bounty Ịchụ nta',
    accountsTitle: 'Akaụntụ & Ịbanye na',
