    accountsB5: 'Ndị otu ọhụrụ:',
    allowanceIntro2: 'Text posts na media bụ iche iche ọdọ mmiri. Na-agba ọsọ nke otu adịghị emetụ nke ọzọ, otú a ụbọchị nọrọ na-ebugote video ka na-ahapụ niile iri ederede posts free. Ha abụọ tọgharịa n \'etiti abalị UTC.',
    allowanceHowDesc: 'The iji okwu, na ọ bụ kpachaara anya: ị na-mgbe ebubo maka a post na-adịghị ebipụta, na ị dịghị mgbe bulite a nnukwu faịlụ naanị ka a gwara e mesịa na ị na-apụghị ịkwụ ụgwọ maka ya.',
    allowanceStep1: 'The ngwa enyocha price megide ihe ị na-ama posted taa na enen gị obere akpa nwere ike ikpuchi ya. Ọ dịghị ihe a na-ebo ebubo, ọ dịghịkwa ihe a ga-ebugo ruo mgbe ọ gafere.',
    allowanceStep2: 'Gị post na-aga ndụ kpọmkwem dị ka ọ ga-n \'ime free allowance. Mbipụta anaghị echere ịkwụ ụgwọ.',
    allowanceBadgeNote: 'Baajị na-ebugharị ọkara abụọ n \'otu oge — ego nnwere onwe buru ibu na ọnụahịa dị ala na ihe ọ bụla gara aga. The ego bụ otu ubube baajị njide ugbua na-mgbe ịzụrụ DeHub tokens, si 5% na Crab 30% na Megalodon, n\' ihi ya, e nwere otu azịza ihe a baajị bụ uru. Gị allowance abịa site baajị ị akwụ: a tier gbaziri gị site a patron na-egosi na profaịlụ gị, ma ọ dịghị aka gị ha ikenye allowance.',
    badgePriceTitle: 'The n \'ọkwá na-ọnụ na dollar',
    badgeUnlock3: 'Otu ego ahụ mgbe ịzụrụ akara ngosi DeHub, site na 5% na Crab ruo 30% na Megalodon.',
    badgeDelegationB1: 'Otu ọkwa, ọ bụghị otu n \'okpuru:',
    badgeDelegationB1Desc: 'A megalodon agbazinye Megalodon. Akara na-azọrọ mmetụta ị nyere iwu, ya mere ndị ị laghachiri na-ebu ihe ị na-ebu.',
    badgeDelegationB3Desc: 'Hover a nyere baajị n \'ebe ọ bụla na ngwa na ọ aha onye na-akwado ya. O nweghị ihe zoro ezo gbasara ebe ọkwa si.',
    badgeDelegationB4: 'Reversible n \'oge ọ bụla:',
    badgeDelegationB6Desc: 'Oghere ekwesịghị inyefe ọkwa gị dị elu. Họrọ ihe a na-emegheghị emechi ọ na-enye, ma weghachite mmadụ na King Cobra n \'emeghị ha Megalodon.',
    msg7: 'Tinye faịlụ nakwa dị ka foto na video, na ekwentị, mbadamba na desktọọpụ myiri',
    boostPower: '1) Ọganihu',
    timelineBomberDesc2: 'Ndị na-eso ụzọ gị na-ahụ ọkwa gị n \'ihu onye ọ bụla ọzọ — King Cobra na-eti Megalodon maka ndị họọrọ ịnụ n\' aka gị. Na-emeghe na King Cobra. Biri ugbu a.',
