    feedsTranslate: 'Automatic Translation:',
    feedsTranslateDesc: 'Posts na kwuru ịsụgharị n \'asụsụ gị dị ka ị pịgharịa, na ihe karịrị otu narị asụsụ, na-enweghị obere akpa njikọ na ọ dịghị ọnọdụ ịchọta. Kpatụ site na nke mbụ n\' oge ọ bụla.',
    communitiesDesc2: 'Ihe omume gbasaa obodo na oge-gburugburu mmemme. A obodo ma ọ bụ n \'elu ikpo okwu nwere ike ịtọọ oge ihe omume, na-ebipụta a raara onwe ya nye omume page na zuru ezu zuru ezu, na ka ndị òtù na-eso tinyere ndụ mgbe ọ na-amalite. Ọnụ, obodo na ihe omume na-enye gburugburu ebe obibi ngwaọrụ iji hazie gburugburu a na-akọrọ mmasị na-eme ka ndị mmadụ na-abịa azụ.',
    communitiesB2: 'Community Feeds:',
    communitiesB3: 'Events:',
    communitiesB3Desc: 'Chọgharịa n \'elu ikpo okwu na obodo ihe, na-emeghe ihe omume page maka zuru atụmatụ na zuru ezu, na-eso tinyere ndụ ozugbo ihe omume amalite.',
    stagesDesc2: 'Ihe na-esetịpụ DeHub Stages iche bụ mmepụta oyi akwa. Ndị ọbịa na-enweta ụda ụda DJ nke na-agwakọta mmetụta dị mma, obere egwu ha na ụlọ redio dị ndụ n \'ime ụlọ e bipụtara, gbakwunyere mmetụta olu, ya mere, ọkwa nwere ike ịdị ka ihe ngosi emepụtara karịa oku ogbako. Ndị ọbịa nwere ike ịkekọrịta ihuenyo ha, na-agba ihe niile site na ihe nchọgharị na-enweghị OBS ma ọ bụ igodo iyi, ma na-ahazi ụlọ n\' ihu ka ndị na-ege ntị na-eche tupu ọnụ ụzọ emeghe.',
    stagesDesc3: 'Ime ụlọ ahụ nwekwara ike ịgụta ọnụ. Live ndepụta okwu caption ọ bụla ọkà okwu ka ha na-ekwu okwu na-sụgharịrị n \'ime ihe ọ bụla asụsụ onye ọ bụla na-ege ntị na-agụ na, otú a ogbo nwere ike soro na a asụsụ ọ dịghị onye na ogbo na-ekwu okwu. Live dubbing na-aga otu nzọụkwụ n\' ihu na-ekwu okwu ọnụ ụlọ n \'olu dara ụda na nnabata onwe cloned olu, ụgwọ site nkeji na DeHub tokens. A ndụ transcript drawer na ederede-na-ekwu okwu na-ụlọ usable enweghị a igwe okwu, na a persistent akuku mini-ọkpụkpọ na-ahapụ gị na-eme nchọgharị na ndị ọzọ nke ngwa mgbe a ogbo na-egwuri.',
    stagesB1: 'Host & Speak:',
    stagesB1Desc: 'Malite a ogbo, òkù ọkà okwu na ogbo, ogbi ma ọ bụ wepụ sonyere, na jikwaa ime ụlọ na ezigbo oge si usu njikwa.',
    stagesB2: 'Reactions & Soundboard:',
    stagesB3: 'Transcripts & TTS:',
    stagesB3Desc: 'A ndụ transcript drawer captions ime ụlọ dị ka ọ na-eme, na ederede-na-ekwu okwu ka ị na-ekere òkè na-enweghị a igwe okwu.',
    stagesB5: 'Usoro iheomume & Ncheta:',
    stagesB5Desc: 'Kpọsaa ọkwa tupu oge eruo na njikọ ịkpọ òkù dị mkpụmkpụ na kaadị òkè nke ya. Onye ọ bụla nke setịpụrụ a ncheta na-mara ọkwa mgbe ọ bụ banyere na-amalite, na ọzọ oge ọ na-aga na-ebi ndụ.',
