    importantNoticeText: 'DeHub na-arụ ọrụ dị ka protokọl enweghị etiti. Ọdịdị enweghị etiti pụtara na mmekọrịta nwere ike ịpụta ìhè na blockchain ọha.',
    lastUpdatedDate: '29 Septemba 2026',
    doCollectItem1: 'Ihe nchọpụta ị banyere na — adreesị ozi-e ma ọ bụ nọmba ekwentị ma ọ bụrụ na ị họọrọ otu n \'ime ụzọ ndị ahụ, njirimara Google, Apple ma ọ bụ Telegram na-alaghachi ma ọ bụrụ na ị banye na mmekọrịta mmadụ na ibe ya, ma ọ bụ nzere ọha na eze nke passkey. Nbanye obere akpa na-enye anyị ihe ọ bụla ma e wezụga adreesị ọha gị.',
    doCollectItem7: 'Ihe ị na-ahọrọ ịgbanwee na: a nọmba ekwentị maka ederede Ịma Ọkwa, ma ndị ọzọ na-ahụ mgbe ị bụ online, na mpụga na-elekọta mmadụ akaụntụ ị jikọọ maka multi-posting.',
    doCollectItem8: 'Nke peeji nke na-eleta na otú ndị mmadụ na-akpali n \'etiti ha, otú anyị nwere ike ịhụ ihe na-arụ ọrụ. Gị onwe gị nleta gị Mgbakwunye peeji nke na-adịghị agụta.',
    dontCollectItem6: 'Nkọwa kaadị gị, ma ọ dịghị mgbe ederede nke ozi ezoro ezo gị na njedebe — ndị ahụ enweghị ike ịgụta anyị. Foto, vidiyo na faịlụ dị na ozi, na ozi nye onye na-emeghebeghị ezoro ezo, ezoro ezo na njedebe.',
    thirdPartyItem6: 'DeHub onwe ingest eburu ndụ video, na Livepeer dị ka a fallback, na Agora eburu ndụ audio ụlọ',
    thirdPartyItem8: 'Text na media ị na-eziga ka a ọgbọ, translation, captioning ma ọ bụ dubbing atụmatụ na-agafere na-eweta na-agba ọsọ ya, n \'ihi na na arịrịọ naanị. Ederede nkeonwe — ozi, nzaghachi na nkata nnyemaaka — anaghị ezigara onye na-eweta ọrụ nke ụgbọ oloko n\' efu na ihe ọ na-enweta.',
    thirdPartyItem9Prefix: 'Ịzụta & ịkwụ ụgwọ na kaadị:',
    thirdPartyItem9: 'MoonPay ere ETH na USDC site kaadị, na nso Intents, deBridge na decentralized mgbanwe tọghata kaadị ị na-akwụ na; onye ọ bụla na-ahụ ugwo ọ njikwa',
    thirdPartyItem10Prefix: 'Multi-ikenye:',
    thirdPartyItem10: 'Mgbe ị jikọtara akaụntụ mmekọrịta ndị ọzọ, a na-enyefe posts ị họọrọ iziga na nyiwe ndị ahụ site na ọrụ nzipu ozi, na Farcaster site na onye ntinye aka ị kwadoro',
    dataSovereigntyItem5: 'Ị na-ahọrọ ma usoro AI nwere ike ịzụ n \'ọrụ gị. Ọ na-ekwe ọ gwụla ma ị gbanyụọ ya na Ntọala, na gị nhọrọ bipụtara crawlers na peeji nke anyị na-achịkwa',
    dataSovereigntyItem6: 'Ị nwere ike ihichapụ akaụntụ gị onwe gị na Ntọala; a na-ehichapụ profaịlụ gị, bulite na mgbasa ozi echekwara, gụnyere mbipụta ndabere,',
    doCollectItem5: 'Ihe ndekọ ịkwụ ụgwọ maka ihe ọ bụla ị zụrụ, ma ọ biri site na Stripe ma ọ bụ na yinye, edobere maka ịza ajụjụ na esemokwu. Nọmba kaadị ka Stripe na-edozi ya ma ọ naghị erute anyị aka.',
    thirdPartyItem4: 'Stripe usoro kaadị ịkwụ ụgwọ na esetịpụ kaadị nkọwa; anyị na-enweta naanị N \'ihi',
    thirdPartyItem4Prefix: 'Ịkwụ ụgwọ:',
